import { useGLTF } from "@react-three/drei";
import { useFrame, useThree } from "@react-three/fiber";
import { useEffect, useMemo, useRef } from "react";
import * as THREE from "three";
import { assetUrl } from "../../lib/assetUrl";
import { extendGltf } from "./gltfExtensions";
import { signalState, type Lamp } from "./signalCycle";

// Generated by tools/city3/signals.py: one post and 3-lamp head per junction corner, lamp meshes named sig_<ns|ew>_<colour>.
const MODEL = assetUrl("/assets/world-signals.glb");
const LAMP_ON = 0.9;
const LAMP_OFF = 0.04;

/** Traffic signals at the Bazaar junctions, cycling on a fixed-time plan. */
export function IntersectionSignals() {
  const gl = useThree((s) => s.gl);
  const gltf = useGLTF(MODEL, true, true, extendGltf(gl));
  const lamps = useMemo(() => {
    const found = new Map<string, THREE.MeshStandardMaterial>();
    gltf.scene.traverse((o) => {
      const mat = (o as THREE.Mesh).material as THREE.MeshStandardMaterial | undefined;
      if (mat?.name?.startsWith("sig_") && /_(red|yellow|green)$/.test(mat.name)) found.set(mat.name, mat);
    });
    return found;
  }, [gltf]);
  const shown = useRef("");
  useEffect(() => () => { shown.current = ""; }, [lamps]);
  useFrame(({ clock }) => {
    const state = signalState(clock.elapsedTime);
    const key = state.ns + state.ew;
    if (key === shown.current) return;
    shown.current = key;
    for (const phase of ["ns", "ew"] as const) {
      for (const colour of ["red", "yellow", "green"] as Lamp[]) {
        const mat = lamps.get(`sig_${phase}_${colour}`);
        if (mat) mat.emissiveIntensity = state[phase] === colour ? LAMP_ON : LAMP_OFF;
      }
    }
  });
  return <primitive object={gltf.scene} />;
}
